const{chromium}=require('C:/Users/GuillaumePelletier/Documents/GitHub/Gaume/spacexr-atmosphere/node_modules/playwright');const fs=require('node:fs');
const out='C:/Users/GuillaumePelletier/Documents/GitHub/SpaceXR/.cache/existing-tiles';fs.mkdirSync(out,{recursive:true});
(async()=>{const browser=await chromium.launch({channel:'chrome',headless:true,args:['--enable-unsafe-webgpu','--use-angle=d3d11','--ignore-gpu-blocklist']});try{const results=[];
for(const[name,path,peak]of[['orbit','orbital.html?view=horizon&sse=20',false],['crest','atmosphere.html?sunset=1&sse=20',true]]){
const page=await browser.newPage({viewport:{width:1200,height:860}}),errors=[],dem=new Set(),imagery=new Set(),legacy=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text());});page.on('request',r=>{const url=r.url();if(url.includes('elevation-tiles-prod/terrarium/'))dem.add(url);if(/mt[0-3]\.google\.com\/vt\//.test(url))imagery.add(url);if(url.includes('earth_map.jpg'))legacy.push(url);});
await page.goto('http://127.0.0.1:5189/'+path);await page.waitForFunction(()=>window.earthDemo?.earth.atmosphereReady||document.body.dataset.error==='true',{},{timeout:60000});if(peak)await page.evaluate(()=>window.earthDemo.earth.camera.pitch=89*Math.PI/180);await page.waitForTimeout(10000);await page.screenshot({path:out+'/'+name+'.png'});
const state=await page.evaluate(()=>({stats:document.querySelector('#stats').textContent,errors:window.earthDemo.errors,attribution:document.querySelector('#attribution').textContent}));results.push({name,errors,state,mapzenRequests:dem.size,existingImageryRequests:imagery.size,legacyRequests:legacy.length,decoderWorkers:page.workers().length});await page.evaluate(()=>window.earthDemo.dispose());await page.close();}
fs.writeFileSync(out+'/results.json',JSON.stringify(results,null,2));console.log(JSON.stringify(results,null,2));if(results.some(r=>r.errors.length||r.state.errors.length||!r.mapzenRequests||!r.existingImageryRequests||r.legacyRequests||r.decoderWorkers!==2))throw Error('Existing tile pipeline validation failed');
}finally{await browser.close();}})().catch(e=>{console.error(e);process.exitCode=1;});
